// --- Setup Function ---
void setup() {
  Serial.begin(115200);
  Serial.println("Vortex AI Booting...");

  tft.init();
  tft.setRotation(1); // Landscape: 320x240
  tft.fillScreen(TFT_BLACK);

  // Initialize SD Card
  if (!SD.begin(5)) { // Use default SS pin for SD
    Serial.println("SD Card initialization failed!");
    tft.drawString("SD Card Error!", 160, 120, 2);
  } else {
    Serial.println("SD Card initialized.");
    // Create LLM directory if it doesn't exist
    if (!SD.exists(llmFolder)) {
      SD.mkdir(llmFolder);
      Serial.println("Created LLM models directory.");
    }
  }

  // Connect to WiFi
  WiFi.begin(ssid, password);
  Serial.print("Connecting to WiFi");
  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
    Serial.print(".");
  }
  Serial.println(" WiFi connected.");
  Serial.println("IP address: " + WiFi.localIP());

  // Initial UI Draw
  drawUI();

  // Start background tasks
  updateFirmwareCheck(); // Check for firmware updates initially
}

