// --- Network Functions ---
void updateFirmwareCheck() {
  if (WiFi.status() == WL_CONNECTED) {
    HTTPClient http;
    http.begin(firmwareUpdateUrl);
    int httpCode = http.GET();

    if (httpCode == HTTP_CODE_OK) {
      String payload = http.getString();
      // Assuming the server returns a JSON like: {"version": "1.0.1"}
      StaticJsonDocument<100> doc;
      DeserializationError error = deserializeJson(doc, payload);
      if (!error) {
        latestFirmwareVersion = doc["version"];
        Serial.println("Latest firmware version: " + latestFirmwareVersion);
        tft.setTextSize(1);
        tft.setTextColor(TFT_YELLOW);
        tft.setCursor(15, 115);
        tft.print("Update: " + latestFirmwareVersion); // Update status display

        // Basic version comparison (replace with a more robust library if needed)
        if (latestFirmwareVersion > firmwareVersion) {
           displayMessage("Firmware update available!");
        }
      } else {
        Serial.print("JSON parsing error: ");
        Serial.println(error.c_str());
      }
    } else {
      Serial.printf("HTTP GET failed, code: %d\n", httpCode);
    }
    http.end();
  } else {
    Serial.println("WiFi not connected, cannot check for updates.");
  }
}

