// Helper function to draw centered text
void TFT_eSPI::drawCentreText(const char *text, int32_t x, int32_t y, uint8_t font, uint32_t color) {
  int32_t width = getUTF8TextWidth(text, font);
  drawCentreText(text, x - width / 2, y, font, color);
}

void TFT_eSPI::drawCentreText(const char *text, int32_t x, int32_t y, uint32_t color) {
  drawCentreText(text, x, y, getFont(), color);
}

void TFT_eSPI::drawCentreText(const char *text, int32_t x, int32_t y, uint8_t font, uint32_t color, uint32_t bgcolor) {
    int32_t width = getUTF8TextWidth(text, font);
    int32_t height = getFontHeight(font);
    // We use x,y as the center of the text, so we need to calculate the top-left corner.
    x = x - width / 2;
    y = y - height / 2;
    drawString(text, x, y, font, color, bgcolor);
}

void TFT_eSPI::drawCentreText(const char *text, int32_t x, int32_t y, uint32_t color, uint32_t bgcolor) {
    drawCentreText(text, x, y, getFont(), color, bgcolor);
}
